ST.xhtml:
伺服调用 ();
//检测ECAT通讯连接数量
IF ethercat1.m_master.m_uiactualnoslaves<>13 THEN
	ECAT掉站报警:=TRUE;
	ELSE
	ECAT掉站报警:=FALSE;
END_IF

IF MODE_State<>1 THEN
	伺服一键回原点 ();
	IF NOT 点样测试 THEN
		位置示教 ();
	END_IF

END_IF

IF MODE_State=1 THEN		
	FOR n:=1 TO 10 BY 1 DO
		HMI_打样瓶上料轴3Y.execute[n]:=FALSE;
		HMI_打样瓶上料轴3Y.write[n]:=FALSE;
		HMI_点样轴6X.execute[n]:=FALSE;
		HMI_点样轴6X.write[n]:=FALSE;
		HMI_点样轴7Y.execute[n]:=FALSE;
		HMI_点样轴7Y.write[n]:=FALSE;
		HMI_地轨轴11Y.execute[n]:=FALSE;
		HMI_地轨轴11Y.write[n]:=FALSE;
		HMI_上样轴4X轴.execute[n]:=FALSE;
		HMI_上样轴4X轴.write[n]:=FALSE;
		HMI_上样轴5Z轴.execute[n]:=FALSE;
		HMI_上样轴5Z轴.write[n]:=FALSE;	
	END_FOR
		HMI_HandWheel_3Y:=FALSE;
		HMI_HandWheel_4X:=FALSE;
		HMI_HandWheel_5Z:=FALSE;
		HMI_HandWheel_6X:=FALSE;
		HMI_HandWheel_7Y:=FALSE;
		HMI_HandWheel_8Y:=FALSE;
		HMI_HandWheel_9X:=FALSE;
		HMI_HandWheel_10Z:=FALSE;
		HMI_HandWheel_11Y:=FALSE;


END_IF

//将外部脉冲发生器的数值传给虚拟轴Encoder.fActPosition SMC_FreeEncoder.fActPosition:=Encoder.fActPosition;
//脉冲发生器使能 HC_Counter_0( Axis:=Encoder , Enable:= 急停 AND NOT 手自动 , Invert:= , Valid=> , Busy=> , Position=> , Velocity=> , Direction=> , Error=> , ErrorID=> );
IF MODE_State<>1 THEN //调用手轮控制块 FB_HandWheel_0( Axis_Spindle:=SMC_FreeEncoder , AXIS_1:=打样瓶上料轴3Y , AXIS_2:= 上样轴4X轴 , AXIS_3:= 上样轴5Z轴 , AXIS_4:= 点样轴6X , AXIS_5:= 点样轴7Y , AXIS_6:= 拍照轴8Y , AXIS_7:= 刮板轴9X , AXIS_8:= 刮板轴10Z, AXIS_9:= 地轨轴11Y , Speed_X1:= 倍率X1 , Speed_X10:= 倍率X10, Speed_X100:= 倍率X100, Reset:= 复位, HandWheel_3Y:= HMI_HandWheel_3Y , HandWheel_4X:= HMI_HandWheel_4X, HandWheel_5Z:= HMI_HandWheel_5Z, HandWheel_6X:= HMI_HandWheel_6X, HandWheel_7Y:= HMI_HandWheel_7Y, HandWheel_8Y:= HMI_HandWheel_8Y, HandWheel_9X:= HMI_HandWheel_9X, HandWheel_10Z:= HMI_HandWheel_10Z, HandWheel_11Y:= HMI_HandWheel_11Y, xStop_1=>打样瓶上料轴3YDATE.xStop , xStop_2=>上样轴4X轴DATE.xStop , xStop_3=> 上样轴5Z轴DATE.xStop, xStop_4=>点样轴6XDATE.xStop , xStop_5=>点样轴7YDATE.xStop , xStop_6=>拍照轴8YDATE.xStop , xStop_7=>刮板轴9XDATE.xStop , xStop_8=>刮板轴10ZDATE.xStop , xStop_9=>地轨轴11YDATE.xStop, Error => , ErrorID => , ); END_IF

//一键回原点
IF 一键回原点 THEN
	IF MODE_State <>1    THEN
	IF 一键回原点 AND NOT ManualAuto THEN
		玻璃上料轴1ZDATE.xHome  :=TRUE;
	玻璃上料轴2ZDATE.xHome  :=TRUE;
	刮板轴10ZDATE.xHome :=TRUE;
	上样轴5Z轴DATE .xHome :=TRUE;
	点样轴6XDATE  .xHome :=TRUE;
	点样轴7YDATE .xHome :=TRUE;
	地轨轴11YDATE .xHome :=TRUE;
	HOME_1STEP:=1;
	HOME_2STEP:=1;
	END_IF
	END_IF

	IF 玻璃上料轴1ZDATE.bHomed  THEN
		玻璃上料轴1ZDATE.xHome  :=FALSE;
	END_IF

	IF 玻璃上料轴2ZDATE.bHomed  THEN
		玻璃上料轴2ZDATE.xHome  :=FALSE;
	END_IF

	IF 点样轴6XDATE.bHomed  THEN
		点样轴6XDATE.xHome  :=FALSE;
	END_IF

	IF 点样轴7YDATE.bHomed  THEN
		点样轴7YDATE.xHome  :=FALSE;
	END_IF

	IF 地轨轴11YDATE.bHomed  THEN
		地轨轴11YDATE.xHome  :=FALSE;
	END_IF

	//刮板拍照回原点流程
	CASE HOME_1STEP OF
		1 :
		IF 刮板轴10ZDATE.bHomed THEN
			刮板轴10ZDATE.xHome :=FALSE;
			刮板轴9XDATE.xHome :=TRUE;
			拍照轴8YDATE.xHome :=TRUE;
			HOME_1STEP:=2;
			END_IF
		2:
		IF 刮板轴9XDATE.bHomed THEN
			刮板轴9XDATE.xHome :=FALSE;
		END_IF
		IF 拍照轴8YDATE.bHomed  THEN
			拍照轴8YDATE.xHome :=FALSE;
		END_IF
		IF 刮板轴10ZDATE.bHomed AND 刮板轴9XDATE.bHomed THEN
			HOME_1STEP:=0;
		END_IF

	END_CASE
	//上样点样回原点流程
	CASE HOME_2STEP OF
		1 :
		IF 上样轴5Z轴DATE.bHomed THEN
			上样轴5Z轴DATE.xHome :=FALSE;
			上样轴4X轴DATE .xHome :=TRUE;
			打样瓶上料轴3YDATE.xHome :=TRUE;
			HOME_2STEP:=2;
			END_IF
		2:
		IF 上样轴4X轴DATE.bHomed THEN
			上样轴4X轴DATE.xHome :=FALSE;
		END_IF
		IF 打样瓶上料轴3YDATE.bHomed  THEN
			打样瓶上料轴3YDATE.xHome :=FALSE;
		END_IF
		IF 打样瓶上料轴3YDATE.bHomed AND 上样轴4X轴DATE.bHomed THEN
			HOME_2STEP:=0;
		END_IF

	END_CASE
	IF 玻璃上料轴1ZDATE.bHomed AND 玻璃上料轴2ZDATE.bHomed AND 点样轴6XDATE.bHomed AND 点样轴7YDATE.bHomed AND 地轨轴11YDATE.bHomed AND 刮板轴10ZDATE.bHomed AND 刮板轴9XDATE.bHomed AND 上样轴5Z轴DATE.bHomed AND 上样轴4X轴DATE.bHomed AND 拍照轴8YDATE.bHomed  AND 打样瓶上料轴3YDATE.bHomed THEN
		一键回原点:=FALSE;
	END_IF
END_IF

//玻璃上料轴1Z伺服控制 FB_SERVOAXIS_0( AXIS:= 玻璃上料轴1Z , //轴名称 xEnable:=急停 , //轴使能 xHome:= 玻璃上料轴1ZDATE.xHome, //轴回零命令 xJogPos:=玻璃上料轴1ZDATE.xJogPos OR Z1JOG_pos , //轴正转命令 xJogNeg:=玻璃上料轴1ZDATE.xJogNeg OR Z1JOG_neg , //轴反转命令 xStop:= 玻璃上料轴1ZDATE.xStop , //轴停止命令 xMoveAbs:= 玻璃上料轴1ZDATE.xMoveAbs , //轴绝对定位命令 xMoveRel:= 玻璃上料轴1ZDATE.xMoveRel, //轴相对定位命令 XReset:= 玻璃上料轴1ZDATE.XReset OR 复位 , //轴复位 fAbsTarget:= 玻璃上料轴1ZDATE.fAbsTarget , //轴绝对定位距离 fRelTarget:=玻璃上料轴1ZDATE.fRelTarget , //轴相对移动距离 fVelocity:= 玻璃上料轴1ZDATE.fVelocity , //轴定位速度 fAcc:=1000.0 , //轴加速度 fDec:= 1000.0, //轴减速度 fJogVel:= 15.0 , //轴JOG速度 bEnabled=> 玻璃上料轴1ZDATE.bEnabled , //轴使能完成 bHomed=> 回零完成1Z , //轴回原点完成 bBusy=> 玻璃上料轴1ZDATE.bBusy , //轴运行中 bError=> 玻璃上料轴1ZDATE.bError , //轴错误 iErrorCode=>玻璃上料轴1ZDATE.iErrorCode , //轴错误代码 fActPos=>玻璃上料轴1ZDATE.fActPos , //轴当前位置 fActVel=>玻璃上料轴1ZDATE.fActVel , //轴当前速度 bAbMoveDone=>玻璃上料轴1ZDATE.bAbMoveDone , //轴绝对定位完成 bReMoveDone =>玻璃上料轴1ZDATE.bReMoveDone ,); //轴相对定位完成 玻璃上料轴1ZDATE.bHomed S= 回零完成1Z; IF 玻璃上料轴1ZDATE.xHome THEN 玻璃上料轴1ZDATE.bHomed:=FALSE; END_IF
//玻璃上料轴2Z伺服控制 FB_SERVOAXIS_1( AXIS:= 玻璃上料轴2Z , //轴名称 xEnable:=急停 , //轴使能 xHome:= 玻璃上料轴2ZDATE.xHome, //轴回零命令 xJogPos:=玻璃上料轴2ZDATE.xJogPos OR Z2JOG_POS , //轴正转命令 xJogNeg:=玻璃上料轴2ZDATE.xJogNeg OR Z2JOG_NEG , //轴反转命令 xStop:= 玻璃上料轴2ZDATE.xStop , //轴停止命令 xMoveAbs:= 玻璃上料轴2ZDATE.xMoveAbs , //轴绝对定位命令 xMoveRel:= 玻璃上料轴2ZDATE.xMoveRel, //轴相对定位命令 XReset:= 玻璃上料轴2ZDATE.XReset OR 复位 , //轴复位 fAbsTarget:= 玻璃上料轴2ZDATE.fAbsTarget , //轴绝对定位距离 fRelTarget:=玻璃上料轴2ZDATE.fRelTarget , //轴相对移动距离 fVelocity:= 玻璃上料轴2ZDATE.fVelocity , //轴定位速度 fAcc:=1000.0 , //轴加速度 fDec:= 1000.0, //轴减速度 fJogVel:= 15.0 , //轴JOG速度 bEnabled=> 玻璃上料轴2ZDATE.bEnabled , //轴使能完成 bHomed=> 回零完成2Z , //轴回原点完成 bBusy=> 玻璃上料轴2ZDATE.bBusy , //轴运行中 bError=> 玻璃上料轴2ZDATE.bError , //轴错误 iErrorCode=>玻璃上料轴2ZDATE.iErrorCode , //轴错误代码 fActPos=>玻璃上料轴2ZDATE.fActPos , //轴当前位置 fActVel=>玻璃上料轴2ZDATE.fActVel , //轴当前速度 bAbMoveDone=>玻璃上料轴2ZDATE.bAbMoveDone , //轴绝对定位完成 bReMoveDone =>玻璃上料轴2ZDATE.bReMoveDone ,); //轴相对定位完成 玻璃上料轴2ZDATE.bHomed S= 回零完成2Z; IF 玻璃上料轴2ZDATE.xHome THEN 玻璃上料轴2ZDATE.bHomed:=FALSE; END_IF
FB_SERVOAXIS_2( AXIS:= 打样瓶上料轴3Y , //轴名称 xEnable:=急停 , //轴使能 xHome:= 打样瓶上料轴3YDATE.xHome, //轴回零命令 xJogPos:=打样瓶上料轴3YDATE.xJogPos , //轴正转命令 xJogNeg:=打样瓶上料轴3YDATE.xJogNeg , //轴反转命令 xStop:= 打样瓶上料轴3YDATE.xStop , //轴停止命令 xMoveAbs:= 打样瓶上料轴3YDATE.xMoveAbs , //轴绝对定位命令 xMoveRel:= 打样瓶上料轴3YDATE.xMoveRel, //轴相对定位命令 XReset:= 打样瓶上料轴3YDATE.XReset OR 复位, //轴复位 fAbsTarget:= 打样瓶上料轴3YDATE.fAbsTarget , //轴绝对定位距离 fRelTarget:=打样瓶上料轴3YDATE.fRelTarget , //轴相对移动距离 fVelocity:= 打样瓶上料轴3YDATE.fVelocity , //轴定位速度 fAcc:=500.0 , //轴加速度 fDec:= 500.0 , //轴减速度 fJogVel:= 50.0 , //轴JOG速度 bEnabled=> 打样瓶上料轴3YDATE.bEnabled , //轴使能完成 bHomed=> 回零完成3Y , //轴回原点完成 bBusy=> 打样瓶上料轴3YDATE.bBusy , //轴运行中 bError=> 打样瓶上料轴3YDATE.bError , //轴错误 iErrorCode=>打样瓶上料轴3YDATE.iErrorCode , //轴错误代码 fActPos=>打样瓶上料轴3YDATE.fActPos , //轴当前位置 fActVel=>打样瓶上料轴3YDATE.fActVel , //轴当前速度 bAbMoveDone=>打样瓶上料轴3YDATE.bAbMoveDone , //轴绝对定位完成 bReMoveDone =>打样瓶上料轴3YDATE.bReMoveDone ,); //轴相对定位完成 打样瓶上料轴3YDATE.bHomed S= 回零完成3Y; IF 打样瓶上料轴3YDATE.xHome THEN 打样瓶上料轴3YDATE.bHomed:=FALSE; END_IF
//点样轴6X伺服控制 FB_SERVOAXIS_3( AXIS:= 点样轴6X , //轴名称 xEnable:=急停 , //轴使能 xHome:= 点样轴6XDATE.xHome, //轴回零命令 xJogPos:=点样轴6XDATE.xJogPos , //轴正转命令 xJogNeg:=点样轴6XDATE.xJogNeg , //轴反转命令 xStop:= 点样轴6XDATE.xStop , //轴停止命令 xMoveAbs:= 点样轴6XDATE.xMoveAbs , //轴绝对定位命令 xMoveRel:= 点样轴6XDATE.xMoveRel, //轴相对定位命令 XReset:= 点样轴6XDATE.XReset OR 复位, //轴复位 fAbsTarget:= 点样轴6XDATE.fAbsTarget , //轴绝对定位距离 fRelTarget:=点样轴6XDATE.fRelTarget , //轴相对移动距离 fVelocity:= 点样轴6XDATE.fVelocity , //轴定位速度 fAcc:=5500.0 , //轴加速度 fDec:= 5500.0, //轴减速度 fJogVel:= 50.0 , //轴JOG速度 bEnabled=> 点样轴6XDATE.bEnabled , //轴使能完成 bHomed=> 回零完成6X , //轴回原点完成 bBusy=> 点样轴6XDATE.bBusy , //轴运行中 bError=> 点样轴6XDATE.bError , //轴错误 iErrorCode=>点样轴6XDATE.iErrorCode , //轴错误代码 fActPos=>点样轴6XDATE.fActPos , //轴当前位置 fActVel=>点样轴6XDATE.fActVel , //轴当前速度 bAbMoveDone=>点样轴6XDATE.bAbMoveDone , //轴绝对定位完成 bReMoveDone =>点样轴6XDATE.bReMoveDone ,); //轴相对定位完成 点样轴6XDATE.bHomed S=回零完成6X; IF 点样轴6XDATE.xHome THEN 点样轴6XDATE.bHomed:=FALSE; END_IF
//点样轴7Y伺服控制 FB_SERVOAXIS_4( AXIS:= 点样轴7Y , //轴名称 xEnable:=急停 , //轴使能 xHome:= 点样轴7YDATE.xHome, //轴回零命令 xJogPos:=点样轴7YDATE.xJogPos , //轴正转命令 xJogNeg:=点样轴7YDATE.xJogNeg , //轴反转命令 xStop:= 点样轴7YDATE.xStop , //轴停止命令 xMoveAbs:= 点样轴7YDATE.xMoveAbs , //轴绝对定位命令 xMoveRel:= 点样轴7YDATE.xMoveRel, //轴相对定位命令 XReset:= 点样轴7YDATE.XReset OR 复位, //轴复位 fAbsTarget:= 点样轴7YDATE.fAbsTarget , //轴绝对定位距离 fRelTarget:=点样轴7YDATE.fRelTarget , //轴相对移动距离 fVelocity:= 点样轴7YDATE.fVelocity , //轴定位速度 fAcc:=500.0 , //轴加速度 fDec:= 500.0 , //轴减速度 fJogVel:= 50.0 , //轴JOG速度 bEnabled=> 点样轴7YDATE.bEnabled , //轴使能完成 bHomed=> 回零完成7Y, //轴回原点完成 bBusy=> 点样轴7YDATE.bBusy , //轴运行中 bError=> 点样轴7YDATE.bError , //轴错误 iErrorCode=>点样轴7YDATE.iErrorCode , //轴错误代码 fActPos=>点样轴7YDATE.fActPos , //轴当前位置 fActVel=>点样轴7YDATE.fActVel , //轴当前速度 bAbMoveDone=>点样轴7YDATE.bAbMoveDone , //轴绝对定位完成 bReMoveDone =>点样轴7YDATE.bReMoveDone ,); //轴相对定位完成 点样轴7YDATE.bHomed S=回零完成7Y; IF 点样轴7YDATE.xHome THEN 点样轴7YDATE.bHomed:=FALSE; END_IF
//拍照轴8Y伺服控制 FB_SERVOAXIS_5( AXIS:= 拍照轴8Y , //轴名称 xEnable:=急停 , //轴使能 xHome:= 拍照轴8YDATE.xHome, //轴回零命令 xJogPos:=拍照轴8YDATE.xJogPos , //轴正转命令 xJogNeg:=拍照轴8YDATE.xJogNeg , //轴反转命令 xStop:= 拍照轴8YDATE.xStop , //轴停止命令 xMoveAbs:= 拍照轴8YDATE.xMoveAbs AND 刮板拍照遮光气缸上位 AND 刮板轴10ZDATE.fActPos<6 , //轴绝对定位命令 xMoveRel:= 拍照轴8YDATE.xMoveRel, //轴相对定位命令 XReset:= 拍照轴8YDATE.XReset OR 复位, //轴复位 fAbsTarget:= 拍照轴8YDATE.fAbsTarget , //轴绝对定位距离 fRelTarget:=拍照轴8YDATE.fRelTarget , //轴相对移动距离 fVelocity:= 拍照轴8YDATE.fVelocity , //轴定位速度 fAcc:=500.0 , //轴加速度 fDec:= 500.0 , //轴减速度 fJogVel:= 50.0 , //轴JOG速度 bEnabled=> 拍照轴8YDATE.bEnabled , //轴使能完成 bHomed=> 回零完成8Y , //轴回原点完成 bBusy=> 拍照轴8YDATE.bBusy , //轴运行中 bError=> 拍照轴8YDATE.bError , //轴错误 iErrorCode=>拍照轴8YDATE.iErrorCode , //轴错误代码 fActPos=>拍照轴8YDATE.fActPos , //轴当前位置 fActVel=>拍照轴8YDATE.fActVel , //轴当前速度 bAbMoveDone=>拍照轴8YDATE.bAbMoveDone , //轴绝对定位完成 bReMoveDone =>拍照轴8YDATE.bReMoveDone ,); //轴相对定位完成 拍照轴8YDATE.bHomed S=回零完成8Y; IF 拍照轴8YDATE.xHome THEN 拍照轴8YDATE.bHomed:=FALSE; END_IF
//刮板轴9X伺服控制 FB_SERVOAXIS_6( AXIS:= 刮板轴9X , //轴名称 xEnable:=急停 , //轴使能 xHome:= 刮板轴9XDATE.xHome, //轴回零命令 xJogPos:=刮板轴9XDATE.xJogPos , //轴正转命令 xJogNeg:=刮板轴9XDATE.xJogNeg , //轴反转命令 xStop:= 刮板轴9XDATE.xStop , //轴停止命令 xMoveAbs:= 刮板轴9XDATE.xMoveAbs AND 刮板轴10ZDATE.fActPos<6, //轴绝对定位命令 xMoveRel:= 刮板轴9XDATE.xMoveRel, //轴相对定位命令 XReset:= 刮板轴9XDATE.XReset OR 复位, //轴复位 fAbsTarget:= 刮板轴9XDATE.fAbsTarget , //轴绝对定位距离 fRelTarget:=刮板轴9XDATE.fRelTarget , //轴相对移动距离 fVelocity:= 刮板轴9XDATE.fVelocity , //轴定位速度 fAcc:=500.0 , //轴加速度 fDec:= 500.0 , //轴减速度 fJogVel:= 50.0 , //轴JOG速度 bEnabled=> 刮板轴9XDATE.bEnabled , //轴使能完成 bHomed=> 回零完成9X, //轴回原点完成 bBusy=> 刮板轴9XDATE.bBusy , //轴运行中 bError=> 刮板轴9XDATE.bError , //轴错误 iErrorCode=>刮板轴9XDATE.iErrorCode , //轴错误代码 fActPos=>刮板轴9XDATE.fActPos , //轴当前位置 fActVel=>刮板轴9XDATE.fActVel , //轴当前速度 bAbMoveDone=>刮板轴9XDATE.bAbMoveDone , //轴绝对定位完成 bReMoveDone =>刮板轴9XDATE.bReMoveDone ,); //轴相对定位完成 刮板轴9XDATE.bHomed S= 回零完成9X; IF 刮板轴9XDATE.xHome THEN 刮板轴9XDATE.bHomed:=FALSE; END_IF
